// One parametric paper field shared by the landing page and the inn.
(() => {
  const KEY='pasteinn-appearance-v1';
  const defaults={background:{base:'#15201b',colors:['#344936','#a29340','#ad572f'],coverage:36,spread:68,x:60,y:48,grain:20,iconTint:true,motion:true,speed:18,seed:48},cards:{layout:'small',preview:true,title:true,body:true,media:true,date:true,crate:true,domain:true,transcript:true}};
  const clone=x=>JSON.parse(JSON.stringify(x));
  const hex=c=>typeof c==='string'&&/^#[\da-f]{6}$/i.test(c);
  function cleanBackground(b={}){const d=defaults.background;return {base:hex(b.base)?b.base:d.base,colors:Array.from({length:3},(_,i)=>hex(b.colors?.[i])?b.colors[i]:d.colors[i]),...Object.fromEntries(['coverage','spread','x','y','grain','speed'].map(k=>[k,Number.isFinite(b[k])?Math.max(0,Math.min(100,b[k])):d[k]])),iconTint:typeof b.iconTint==='boolean'?b.iconTint:d.iconTint,motion:typeof b.motion==='boolean'?b.motion:d.motion,seed:Number.isFinite(b.seed)?Math.abs(b.seed)%100000:d.seed}}
  function cleanCards(c={}){return {layout:['compact','small','large'].includes(c.layout)?c.layout:'small',...Object.fromEntries(Object.keys(defaults.cards).filter(k=>k!=='layout').map(k=>[k,typeof c[k]==='boolean'?c[k]:defaults.cards[k]]))}}
  function clean(value={}){return {background:cleanBackground(value.background),cards:cleanCards(value.cards)}}
  let prefs;try{prefs=clean(JSON.parse(localStorage.getItem(KEY)||'{}'))}catch{prefs=clone(defaults)}
  let current=clone(prefs.background),target=clone(current),preview=null,currentCrate=null;
  function derive(color){if(!prefs.background.iconTint)return clone(prefs.background);const rgb=color.slice(1).match(/../g).map(v=>parseInt(v,16));const shade=f=>'#'+rgb.map(v=>Math.round(v*f).toString(16).padStart(2,'0')).join('');return {...prefs.background,base:shade(.14),colors:[shade(.42),shade(.65),prefs.background.colors[2]]}}
  function effective(crate){return crate?.appearance?.background?cleanBackground(crate.appearance.background):crate?derive(crate.color):prefs.background}
  const bg=document.createElement('canvas'),grain=document.createElement('canvas');bg.className='inn-field';grain.className='inn-grain';bg.setAttribute('aria-hidden','true');grain.setAttribute('aria-hidden','true');document.body.prepend(bg,grain);bg.width=220;bg.height=150;grain.width=480;grain.height=360;
  const ctx=bg.getContext('2d'),gctx=grain.getContext('2d');let noiseKey='',phase=0,last=0,staticFrames=0;
  function random(seed){return ()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return ((t^t>>>14)>>>0)/4294967296}}
  function paintNoise(b){const key=b.seed+':'+Math.round(b.grain);if(key===noiseKey)return;noiseKey=key;const rand=random(b.seed+831),pixels=gctx.createImageData(grain.width,grain.height);
    for(let y=0;y<grain.height;y++)for(let x=0;x<grain.width;x++){const i=(y*grain.width+x)*4,cloud=.5+.28*Math.sin(x*.018+y*.014)+.2*Math.cos(y*.039-x*.012),v=rand(),warm=v>.5?226:29;pixels.data[i]=warm;pixels.data[i+1]=warm+5;pixels.data[i+2]=warm-6;pixels.data[i+3]=Math.round((v>.97?60:Math.pow(Math.abs(v-.5)*2,2)*38)*cloud*b.grain/30)}gctx.putImageData(pixels,0,0);
  }
  const rgb=c=>c.slice(1).match(/../g).map(v=>parseInt(v,16)),mix=(a,b,t)=>'#'+rgb(a).map((v,i)=>Math.round(v+(rgb(b)[i]-v)*t).toString(16).padStart(2,'0')).join('');
  function frame(now){requestAnimationFrame(frame);if(document.hidden||now-last<70)return;last=now;const b=preview||target;
    for(const k of ['coverage','spread','x','y','grain','speed'])current[k]+=(b[k]-current[k])*.12;current.base=rgb(current.base).every((v,i)=>Math.abs(v-rgb(b.base)[i])<5)?b.base:mix(current.base,b.base,.1);current.colors=current.colors.map((c,i)=>rgb(c).every((v,j)=>Math.abs(v-rgb(b.colors[i])[j])<5)?b.colors[i]:mix(c,b.colors[i],.1));current.seed=b.seed;current.motion=b.motion;
    const changing=noiseKey!==b.seed+':'+Math.round(b.grain)||current.base!==b.base||current.colors.some((c,i)=>c!==b.colors[i])||['coverage','spread','x','y','grain','speed'].some(k=>Math.abs(current[k]-b[k])>.1);staticFrames=changing?0:staticFrames+1;const moving=current.motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches;if(!moving&&staticFrames>2)return;if(moving)phase+=current.speed*.000018;
    ctx.fillStyle=current.base;ctx.fillRect(0,0,220,150);const rand=random(current.seed),coverage=current.coverage/100;
    // Long, irregular cut-paper strokes. No radial gradients or isolated blobs.
    for(let i=0;i<11;i++){const cx=(rand()-.5)*current.spread*3.8+current.x*2.2,cy=(rand()-.5)*current.spread*2.4+current.y*1.5,width=35+rand()*180,height=6+rand()*37,tilt=(rand()-.5)*1.3;
      ctx.save();ctx.translate(cx+(moving?Math.sin(phase+i)*9:0),cy+(moving?Math.cos(phase*.6+i)*5:0));ctx.rotate(tilt);ctx.globalAlpha=coverage*(.19+rand()*.55);ctx.fillStyle=current.colors[i%3];ctx.filter='blur(1.3px)';ctx.beginPath();ctx.moveTo(-width/2,-height*.4);ctx.lineTo(-width*.12,-height*.7);ctx.lineTo(width*.54,-height*.2);ctx.lineTo(width*.43,height*.6);ctx.lineTo(-width*.33,height*.4);ctx.closePath();ctx.fill();ctx.restore();}
    paintNoise(current);document.documentElement.style.setProperty('--inn-base',current.base);
  }requestAnimationFrame(frame);
  const dialog=document.createElement('dialog');dialog.id='appearance-dialog';dialog.setAttribute('aria-labelledby','appearance-heading');dialog.innerHTML=`<button type="button" class="dialog-close" data-dismiss aria-label="Close customizer">×</button><h2 id="appearance-heading">Make it yours.</h2><form id="appearance-form"><label>Apply to<select id="appearance-scope"></select></label><div class="customizer-tabs"><button type="button" data-tab="paper" aria-pressed="true">Paper</button><button type="button" data-tab="cards" aria-pressed="false">Cards</button></div><section id="paper-options"><div class="patch-colors"><label>Paper<input type="color" data-bg="base"></label>${[0,1,2].map(i=>`<label>Patch ${i+1}<input type="color" data-patch="${i}"></label>`).join('')}</div>${[['coverage','Color',0,100],['spread','Spread',0,100],['x','Across',0,100],['y','Down',0,100],['grain','Grain',0,60],['speed','Drift',0,60]].map(([k,label,min,max])=>`<label class="range-row">${label}<input type="range" data-bg="${k}" min="${min}" max="${max}"><output data-output="${k}"></output></label>`).join('')}<label class="check-row"><input type="checkbox" data-bg="motion"> Let it drift</label><label class="check-row"><input type="checkbox" data-bg="iconTint"> Follow crate icon colors</label><button type="button" id="reshuffle-paper">Another arrangement ↻</button></section><section id="card-options" hidden><label>Size<select id="card-layout"><option value="compact">Compact</option><option value="small">Small</option><option value="large">Large</option></select></label><div class="card-toggles">${[['preview','URL title card'],['title','Title'],['body','Subtext'],['media','Images & media'],['domain','Link domain'],['date','Date added'],['crate','Crate'],['transcript','Transcript']].map(([k,label])=>`<label class="check-row"><input type="checkbox" data-card="${k}">${label}</label>`).join('')}</div></section><p id="appearance-result" role="status"></p><div class="editor-actions"><button type="button" id="reset-appearance">Use defaults</button><button type="submit" class="save-button">Save</button></div></form>`;document.body.append(dialog);
  const $=id=>document.getElementById(id);let editValue=null,scope='global',getCrates=()=>[],saveCrate=null;
  function fill(){const b=editValue.background;dialog.querySelectorAll('[data-bg]').forEach(el=>{const k=el.dataset.bg;if(el.type==='checkbox')el.checked=b[k];else el.value=b[k]});dialog.querySelectorAll('[data-patch]').forEach(el=>el.value=b.colors[+el.dataset.patch]);dialog.querySelectorAll('[data-output]').forEach(el=>el.textContent=Math.round(b[el.dataset.output]));$('card-layout').value=editValue.cards.layout;dialog.querySelectorAll('[data-card]').forEach(el=>el.checked=editValue.cards[el.dataset.card]);preview=clone(b)}
  function loadScope(){scope=$('appearance-scope').value;const crate=getCrates().find(c=>c.id===scope);editValue={background:clone(effective(crate)),cards:crate?.appearance?.cards?cleanCards(crate.appearance.cards):clone(prefs.cards)};fill();window.InnMenus?.baseline(dialog)}
  function open(crateId='global'){const crates=getCrates();$('appearance-scope').innerHTML='<option value="global">Every crate · defaults</option>'+crates.map(c=>{const o=document.createElement('option');o.value=c.id;o.textContent=c.name;return o.outerHTML}).join('');$('appearance-scope').value=crates.some(c=>c.id===crateId)?crateId:'global';loadScope();$('card-options').hidden=true;$('paper-options').hidden=false;dialog.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tab==='paper')));dialog.querySelector('[data-tab="cards"]').hidden=!crates.length;dialog.showModal();window.InnMenus?.watch(dialog,()=>JSON.stringify({scope,value:editValue}),()=> $('appearance-form').requestSubmit(),()=>{preview=null});}
  $('appearance-scope').onchange=()=>{const next=$('appearance-scope').value;$('appearance-scope').value=scope;const change=()=>{$('appearance-scope').value=next;loadScope()};if(window.InnMenus)InnMenus.change(dialog,change);else change()};
  dialog.addEventListener('input',e=>{const el=e.target;if(el.dataset.bg)editValue.background[el.dataset.bg]=el.type==='checkbox'?el.checked:el.type==='color'?el.value:Number(el.value);if(el.dataset.patch!==undefined){editValue.background.colors[+el.dataset.patch]=el.value;editValue.background.iconTint=false;dialog.querySelector('[data-bg=iconTint]').checked=false}if(el.dataset.bg==='base'){editValue.background.iconTint=false;dialog.querySelector('[data-bg=iconTint]').checked=false}if(el.dataset.card)editValue.cards[el.dataset.card]=el.checked;if(el.id==='card-layout')editValue.cards.layout=el.value;preview=clone(editValue.background);dialog.querySelectorAll('[data-output]').forEach(x=>x.textContent=Math.round(editValue.background[x.dataset.output]));});
  dialog.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{const cards=b.dataset.tab==='cards';$('paper-options').hidden=cards;$('card-options').hidden=!cards;dialog.querySelectorAll('[data-tab]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});
  $('reshuffle-paper').onclick=()=>{editValue.background.seed=Math.floor(Math.random()*100000);fill()};$('reset-appearance').onclick=()=>{const crate=getCrates().find(c=>c.id===scope);editValue=scope==='global'?clone(defaults):{background:derive(crate.color),cards:clone(prefs.cards)};fill()};
  $('appearance-form').onsubmit=async e=>{e.preventDefault();try{if(scope==='global'){localStorage.setItem(KEY,JSON.stringify(editValue));prefs=clean(editValue)}else await saveCrate(scope,clean(editValue));preview=null;target=clone(effective(currentCrate&&getCrates().find(c=>c.id===currentCrate.id)));dialog.close();dispatchEvent(new CustomEvent('inn:appearance'));}catch{$('appearance-result').textContent='Couldn’t save. Your changes are still here.'}};
  dialog.addEventListener('close',()=>{preview=null});
  window.InnSurface={defaults,clean,cleanBackground,cleanCards,open,configure(get,save){getCrates=get;saveCrate=save},select(crate){currentCrate=crate;target=clone(effective(crate))},cards(crate){return crate?.appearance?.cards?cleanCards(crate.appearance.cards):prefs.cards},export(){return clone(prefs)},restore(value){prefs=clean(value);localStorage.setItem(KEY,JSON.stringify(prefs));target=clone(effective(currentCrate));dispatchEvent(new CustomEvent('inn:appearance'))},snapshot(){return clone(target)}};
})();
